create table if not exists public.b2b_awards (id uuid primary key default gen_random_uuid(), rfq_id uuid not null references public.business_rfqs(id) on delete cascade, quote_id uuid not null references public.business_rfq_quotes(id) on delete restrict, buyer_id uuid not null references auth.users(id) on delete restrict, supplier_id uuid not null references auth.users(id) on delete restrict, store_id uuid null references public.stores(id) on delete set null, status text not null default 'awarded' check(status in ('awarded','negotiating','order_ready','ordered','cancelled')), negotiation_id uuid null references public.negotiations(id) on delete set null, order_id uuid null references public.orders(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(rfq_id,quote_id)); alter table public.b2b_awards enable row level security; drop policy if exists b2b_awards_participant_select on public.b2b_awards; create policy b2b_awards_participant_select on public.b2b_awards for select to authenticated using(auth.uid() in (buyer_id,supplier_id));
create table if not exists public.marketplace_app_reviews (id uuid primary key default gen_random_uuid(), app_id uuid not null references public.marketplace_apps(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, rating smallint not null check(rating between 1 and 5), review text null check(review is null or char_length(review)<=2000), status text not null default 'published' check(status in ('published','hidden','under_review')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(app_id,user_id)); alter table public.marketplace_app_reviews enable row level security; drop policy if exists app_reviews_public_select on public.marketplace_app_reviews; drop policy if exists app_reviews_owner_write on public.marketplace_app_reviews; drop policy if exists app_reviews_owner_update on public.marketplace_app_reviews; create policy app_reviews_public_select on public.marketplace_app_reviews for select to anon,authenticated using(status='published'); create policy app_reviews_owner_write on public.marketplace_app_reviews for insert to authenticated with check(user_id=auth.uid()); create policy app_reviews_owner_update on public.marketplace_app_reviews for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create table if not exists public.marketplace_app_revenue_share (id uuid primary key default gen_random_uuid(), app_id uuid not null references public.marketplace_apps(id) on delete cascade, publisher_id uuid not null references auth.users(id) on delete cascade, gross_amount_minor bigint not null check(gross_amount_minor>=0), platform_fee_minor bigint not null default 0 check(platform_fee_minor>=0), publisher_amount_minor bigint not null default 0 check(publisher_amount_minor>=0), currency char(3) not null default 'USD', status text not null default 'pending' check(status in ('pending','recognized','paid','refunded')), reference_type text null, reference_id uuid null, created_at timestamptz not null default now()); alter table public.marketplace_app_revenue_share enable row level security; drop policy if exists app_revenue_publisher_select on public.marketplace_app_revenue_share; create policy app_revenue_publisher_select on public.marketplace_app_revenue_share for select to authenticated using(publisher_id=auth.uid());
create table if not exists public.marketplace_app_sandboxes (id uuid primary key default gen_random_uuid(), app_id uuid not null references public.marketplace_apps(id) on delete cascade, owner_id uuid not null references auth.users(id) on delete cascade, environment text not null default 'sandbox' check(environment='sandbox'), config jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(app_id,owner_id)); alter table public.marketplace_app_sandboxes enable row level security; drop policy if exists app_sandbox_owner_select on public.marketplace_app_sandboxes; drop policy if exists app_sandbox_owner_insert on public.marketplace_app_sandboxes; drop policy if exists app_sandbox_owner_update on public.marketplace_app_sandboxes; create policy app_sandbox_owner_select on public.marketplace_app_sandboxes for select to authenticated using(owner_id=auth.uid()); create policy app_sandbox_owner_insert on public.marketplace_app_sandboxes for insert to authenticated with check(owner_id=auth.uid()); create policy app_sandbox_owner_update on public.marketplace_app_sandboxes for update to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create table if not exists public.agent_identities (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, name text not null check(char_length(trim(name)) between 2 and 120), public_key text null, scopes text[] not null default '{}', status text not null default 'active' check(status in ('active','suspended','revoked')), created_at timestamptz not null default now(), updated_at timestamptz not null default now()); alter table public.agent_identities enable row level security; drop policy if exists agent_identity_owner_select on public.agent_identities; drop policy if exists agent_identity_owner_insert on public.agent_identities; drop policy if exists agent_identity_owner_update on public.agent_identities; create policy agent_identity_owner_select on public.agent_identities for select to authenticated using(owner_id=auth.uid()); create policy agent_identity_owner_insert on public.agent_identities for insert to authenticated with check(owner_id=auth.uid()); create policy agent_identity_owner_update on public.agent_identities for update to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create table if not exists public.agent_access_tokens (id uuid primary key default gen_random_uuid(), agent_id uuid not null references public.agent_identities(id) on delete cascade, token_prefix text not null, token_hash text not null unique, scopes text[] not null default '{}', expires_at timestamptz null, revoked_at timestamptz null, last_used_at timestamptz null, created_at timestamptz not null default now()); alter table public.agent_access_tokens enable row level security; drop policy if exists agent_token_owner_select on public.agent_access_tokens; create policy agent_token_owner_select on public.agent_access_tokens for select to authenticated using(exists(select 1 from public.agent_identities a where a.id=agent_id and a.owner_id=auth.uid()));
create table if not exists public.developer_webhook_endpoints (id uuid primary key default gen_random_uuid(), app_id uuid not null references public.developer_apps(id) on delete cascade, owner_id uuid not null references auth.users(id) on delete cascade, url text not null check(char_length(url) between 10 and 2048), secret_hash text not null, events text[] not null default '{}', active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now()); alter table public.developer_webhook_endpoints enable row level security; drop policy if exists developer_webhook_owner_select on public.developer_webhook_endpoints; drop policy if exists developer_webhook_owner_insert on public.developer_webhook_endpoints; drop policy if exists developer_webhook_owner_update on public.developer_webhook_endpoints; create policy developer_webhook_owner_select on public.developer_webhook_endpoints for select to authenticated using(owner_id=auth.uid()); create policy developer_webhook_owner_insert on public.developer_webhook_endpoints for insert to authenticated with check(owner_id=auth.uid() and exists(select 1 from public.developer_apps a where a.id=app_id and a.owner_id=auth.uid())); create policy developer_webhook_owner_update on public.developer_webhook_endpoints for update to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create table if not exists public.developer_webhook_deliveries (id uuid primary key default gen_random_uuid(), endpoint_id uuid not null references public.developer_webhook_endpoints(id) on delete cascade, event_type text not null, event_id text not null, payload jsonb not null default '{}'::jsonb, status text not null default 'pending' check(status in ('pending','delivered','failed')), attempts integer not null default 0 check(attempts>=0), response_code integer null, last_error text null, delivered_at timestamptz null, created_at timestamptz not null default now(), unique(endpoint_id,event_id)); alter table public.developer_webhook_deliveries enable row level security; drop policy if exists developer_webhook_delivery_owner_select on public.developer_webhook_deliveries; create policy developer_webhook_delivery_owner_select on public.developer_webhook_deliveries for select to authenticated using(exists(select 1 from public.developer_webhook_endpoints e where e.id=endpoint_id and e.owner_id=auth.uid()));
create table if not exists public.developer_oauth_authorizations (id uuid primary key default gen_random_uuid(), app_id uuid not null references public.developer_apps(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, scopes text[] not null default '{}', authorization_code_hash text null unique, access_token_hash text null unique, refresh_token_hash text null unique, expires_at timestamptz null, revoked_at timestamptz null, created_at timestamptz not null default now()); alter table public.developer_oauth_authorizations enable row level security; drop policy if exists developer_oauth_user_select on public.developer_oauth_authorizations; create policy developer_oauth_user_select on public.developer_oauth_authorizations for select to authenticated using(user_id=auth.uid());
create index if not exists b2b_awards_buyer_idx on public.b2b_awards(buyer_id,created_at desc); create index if not exists b2b_awards_supplier_idx on public.b2b_awards(supplier_id,created_at desc); create index if not exists marketplace_app_reviews_app_idx on public.marketplace_app_reviews(app_id,status,created_at desc); create index if not exists marketplace_app_revenue_app_idx on public.marketplace_app_revenue_share(app_id,created_at desc); create index if not exists agent_access_tokens_hash_idx on public.agent_access_tokens(token_hash); create index if not exists developer_webhook_endpoint_app_idx on public.developer_webhook_endpoints(app_id); create index if not exists developer_webhook_delivery_status_idx on public.developer_webhook_deliveries(status,created_at); create index if not exists developer_oauth_app_user_idx on public.developer_oauth_authorizations(app_id,user_id);
